import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/cases/cli-argparse.json';
let raw = readFileSync(p, 'utf8');
// Escape stray raw C0 control chars (but keep structural \n \r \t whitespace intact).
const bad = new RegExp(
  '[' +
    String.fromCharCode(0) + '-' + String.fromCharCode(8) +
    String.fromCharCode(11) + String.fromCharCode(12) +
    String.fromCharCode(14) + '-' + String.fromCharCode(31) +
    ']',
  'g',
);
raw = raw.replace(bad, (m) => '\\u' + m.charCodeAt(0).toString(16).padStart(4, '0'));
const cs = JSON.parse(raw);
const VT = String.fromCharCode(11);
const i = cs.findIndex((c) => c.note && c.note.startsWith('vertical tab'));
cs[i] = { a: VT + '1', b: 'true', note: 'vertical tab (U+000B) is NOT JSON whitespace -> exit 1 Expecting value col 1' };
const d = (n) => '1'.repeat(n);
cs.push({ a: d(4300), b: 'true', note: '4300-digit integer: at the limit, parses fine -> 0' });
cs.push({ a: d(4301), b: 'true', note: 'KEY: 4301-digit int -> exit 1 ValueError Exceeds the limit (4300 digits) for integer string conversion' });
cs.push({ a: '[' + d(4301) + ']', b: 'true', note: 'digit limit applies to ints nested anywhere in --a -> exit 1' });
cs.push({ a: d(4301) + '.0', b: 'true', note: 'same digit count as a FLOAT is fine (no int conversion) -> 0' });
cs.push({ a: '1', b: '{"const":' + d(4301) + '}', note: 'digit limit also applies to --b (schema) -> exit 1' });
cs.push({ a: '[' + Array(3000).fill('1').join(',') + ']', b: '{"type":"array","maxItems":3}', note: '6kB argv value OK; 1 maxItems error' });
writeFileSync(p, JSON.stringify(cs, null, 1));
console.log('cases:', cs.length);

import { readFileSync } from 'node:fs';
const o = JSON.parse(readFileSync('/workspace/probe/observed/cli-argparse.json', 'utf8'));
o.forEach((c, i) => {
  const argv = c.argv ?? ['--a', c.a, '--b', c.b];
  const shown = argv.map((x) => (String(x).length > 24 ? String(x).slice(0, 18) + '..[' + String(x).length + ']' : x));
  const out = c.code === 0 ? JSON.stringify(c.stdout.length > 40 ? c.stdout.slice(0, 34) + '..' : c.stdout) : 'EXIT ' + c.code;
  const err = c.code === 0 ? '' : ' :: ' + c.stderrTail.replace(/\[PYI-\d+:ERROR\][^|]*/g, '<PYI>');
  console.log(`#${String(i).padStart(3)} ${JSON.stringify(shown).slice(0, 76).padEnd(78)} => ${out}${err}`);
});

import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/cases/cli-argparse.json';
const cs = JSON.parse(readFileSync(p, 'utf8'));

const fix = {
  79: 'multi-line JSON instance parses fine; required [y,z] both missing -> 2 errors',
  81: 'both invalid: --a parsed first -> "Expecting property name enclosed in double quotes: line 1 column 2 (char 1)" at test5.py line 11',
  71: 'only the FIRST = splits, value is "1=2" -> "Extra data: line 1 column 2 (char 1)"',
  95: 'raw tab/newline inside a JSON string literal -> "Invalid control character at: line 1 column 3 (char 2)"',
  100: 'unknown "type" value -> exit 1 UnknownType (multi-line message ending with the instance repr)',
  101: 'unresolvable local $ref -> exit 1 jsonschema.exceptions._WrappedReferencingError: PointerToNowhere',
  89: 'bare emoji (unquoted) is invalid JSON -> exit 1 Expecting value col 1',
};
for (const [k, v] of Object.entries(fix)) cs[Number(k)].note = v;

cs.push({ argv: ['--a=--', '--b', 'true'], note: 'equals form lets "--" through as a value -> invalid JSON exit 1' });
cs.push({ argv: ['--a', '1', '--b='], note: '--b= empty via equals -> exit 1, frame is test5.py line 12' });
cs.push({ argv: ['--a', '1', '--b', 'true', ''], note: 'empty-string positional -> "unrecognized arguments: " (trailing space, empty token)' });
cs.push({ argv: ['--a', '1', '--b', 'true', '-'], note: 'lone "-" positional -> unrecognized arguments: -' });
cs.push({ argv: ['--a', '1', '--b', 'true', '='], note: 'bare "=" positional -> unrecognized arguments: =' });
cs.push({ argv: ['--', '-h'], note: 'after --, -h is a positional: help does NOT fire -> required --a, --b' });
cs.push({ argv: ['--h', '--a', '1', '--b', 'true'], note: 'abbreviated --h still triggers help and suppresses the count' });
cs.push({ argv: ['--a', ' 1 ', '--b', ' true '], note: 'spaces around values on both sides are fine -> 0' });
cs.push({ argv: ['--a', ' 1', '--b', 'true'], note: 'NBSP is not JSON whitespace -> exit 1' });
cs.push({ argv: ['--b', 'false', '--a', '1'], note: 'schema false always yields exactly 1 error' });

writeFileSync(p, JSON.stringify(cs, null, 1));
console.log('cases:', cs.length);

import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test5_executable';
const show = (label, args, env) => {
  const r = spawnSync(EXE, args, { encoding: 'utf8', env: env ? { ...process.env, ...env } : process.env });
  console.log('### ' + label + '  exit=' + r.status);
  console.log('  stdout(' + Buffer.byteLength(r.stdout) + ')=' + JSON.stringify(r.stdout));
  console.log('  stderr(' + Buffer.byteLength(r.stderr) + ')=' + JSON.stringify(r.stderr));
};
show('help', ['-h']);
show('no-args', []);
show('missing-b', ['--a', '1']);
show('unrecognized', ['--a', '1', '--b', 'true', '--c', '1']);
show('expected-one', ['--a']);
show('ambiguous', ['--=1']);
show('ignored-explicit', ['--help=x']);
show('ok', ['--a', '1', '--b', 'false']);
show('json-err-a', ['--a', 'x', '--b', 'true']);
show('json-err-b', ['--a', '1', '--b', 'x']);
show('help-COLUMNS-40', ['-h'], { COLUMNS: '40' });
show('err-COLUMNS-40', ['--a', '1'], { COLUMNS: '40' });

import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/cases/cli-argparse.json';
const cs = JSON.parse(readFileSync(p, 'utf8'));
const add = [
  [['--a', '-0', '--b', 'true'], '-0 matches ^-\\d+$ -> consumed -> 0'],
  [['--a', '-00', '--b', 'true'], '-00 matches the regex so consumed, but JSON rejects leading zeros -> exit 1'],
  [['--a', '-1.', '--b', 'true'], '-1. does NOT match ^-\\d*\\.\\d+$ (no digit after dot) -> exit 2 expected one argument'],
  [['--a', '-.', '--b', 'true'], '-. not a number -> exit 2 expected one argument'],
  [['--a', '-1.5e3', '--b', 'true'], 'KEY: -1.5e3 is valid JSON but exponent breaks the regex -> exit 2'],
  [['--a', '--1', '--b', 'true'], '--1 looks like a long option -> exit 2 expected one argument'],
  [['--a', '+1', '--b', 'true'], '+1 does not start with - so it is consumed; JSON rejects + -> exit 1'],
  [['--a', '-1', '--b', '{"type":"integer","minimum":0}'], 'negative int consumed and validated -> 1 minimum error'],
];
for (const [argv, note] of add) cs.push({ argv, note });
writeFileSync(p, JSON.stringify(cs, null, 1));
console.log('cases:', cs.length);
